unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic, unsigned long addr, unsigned long length)
{
    unsigned long val = 0;

    switch (ioapic->ioregsel) {
    case KVM_IOAPIC_REG_SELECT_ID:
        val = (ioapic->id << 2);
        break;
    case KVM_IOAPIC_REG_SELECT_VERSION:
        val = (0x14 << 8) | KVM_IOAPIC_VERSION;
        break;
    case KVM_IOAPIC_REG_SELECT_REDTBL:
        if (ioapic->redirtbl_index < KVM_IOAPIC_NUM_RTES)
            val = ioapic->redirtbl[ioapic->redirtbl_index++];
        break;
    default:
        break;
    }

    return val;
}

unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic,
                                       unsigned long addr,
                                       unsigned long length)
{
    unsigned long val = 0;

    switch (ioapic->ioregsel) {
    case KVM_IOAPIC_REG_SELECT_VERSION:
        val = (KVM_IOAPIC_VERSION << KVM_IOAPIC_VERSION_OFFSET) |
              KVM_IOAPIC_EOI_SUPPORT;
        break;
    case KVM_IOAPIC_REG_SELECT_ID:
        val = (ioapic->id << KVM_IOAPIC_ID_OFFSET);
        break;
    case KVM_IOAPIC_REG_SELECT_REDTBL:
        if (ioapic->redirtbl_idx < KVM_IOAPIC_NUM_RTES) {
            val = ioapic->redirtbl[ioapic->redirtbl_idx];
        }
        break;
    default:
        break;
    }

    return val;
}

unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic, unsigned long addr, unsigned long length)
{
    unsigned long index = ioapic->ioregsel;
    unsigned long ret = 0;

    if (index == KVM_IOAPIC_REG_SELECT_VERSION) {
        ret = ((ioapic->nr_pins - 1) & KVM_IOAPIC_VERSION_NUMBER_MASK) |
              KVM_IOAPIC_VERSION_REVISION(ioapic);
    } else if (index == KVM_IOAPIC_REG_SELECT_ID) {
        ret = (ioapic->id << KVM_IOAPIC_ID_SHIFT) & KVM_IOAPIC_ID_MASK;
    } else if (index >= KVM_IOAPIC_REG_SELECT_REDIRECTION_ENTRIES &&
               index < KVM_IOAPIC_REG_SELECT_REDIRECTION_ENTRIES + ioapic->nr_pins * 2) {
        int entry = (index - KVM_IOAPIC_REG_SELECT_REDIRECTION_ENTRIES) / 2;
        if (entry < ioapic->nr_pins) {
            ret = (index & 1) ?
                  ioapic->regs.redir_entries[entry].high :
                  ioapic->regs.redir_entries[entry].low;
        }
    } else {
        ret = 0; /* Default return for invalid register */
    }

    return ret;
}

unsigned long kvm_ioapic_read_indirect_register(struct kvm_ioapic *ioapic,
                                               unsigned long addr,
                                               unsigned long length)
{
    unsigned long val = 0;

    switch (ioapic->ioregsel) {
    case IOAPIC_REG_SELECT_VERSION:
        val = ((unsigned long)(ioapic->nr_redir_entries - 1)) << 16;
        val |= KVM_IOAPIC_VERSION;
        break;
    case IOAPIC_REG_SELECT_ID:
        val = (unsigned long)ioapic->mpc_id << 24;
        break;
    case IOAPIC_REG_SELECT_REDIR_TABLE:
        if (ioapic->ioregsel_index < ioapic->nr_redir_entries)
            val = ioapic->redir_entries[ioapic->ioregsel_index].bits;
        break;
    default:
        val = 0;
    }

    return val;
}

unsigned long kvm_ioapic_read_indirect_register(struct kvm_ioapic *ioapic,
                                               unsigned long addr,
                                               unsigned long length)
{
    unsigned long index = ioapic->ioregsel;
    unsigned long ret = 0;

    switch (index) {
    case KVM_IOAPIC_REG_ID:
        ret = (ioapic->id << KVM_IOAPIC_ID_SHIFT) & KVM_IOAPIC_ID_MASK;
        break;
    case KVM_IOAPIC_REG_VERSION:
        ret = ((KVM_IOAPIC_VERSION << KVM_IOAPIC_VERSION_SHIFT) &
               KVM_IOAPIC_VERSION_MASK) |
              ((KVM_IOAPIC_NO_REDIRECTION_ENTRIES << KVM_IOAPIC_RENTRY_SHIFT) &
               KVM_IOAPIC_RENTRY_MASK);
        break;
    case KVM_IOAPIC_REG_ARBASE:
        ret = ioapic->arbase;
        break;
    default:
        if (index >= KVM_IOAPIC_REG_RENTRY(0) &&
            index < KVM_IOAPIC_REG_RENTRY(KVM_IOAPIC_RENTRY_NR)) {
            int entry = (index - KVM_IOAPIC_REG_RENTRY(0)) / sizeof(ret);
            ret = ioapic->redir_default[entry];
        }
        break;
    }

    return ret;
}
